<?php require_once __DIR__.'/../config/bootstrap.php';if(current_user()&&current_user()['role']==='admin')redirect('admin/index.php');$err='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$senha=$_POST['senha']??'';$s=db()->prepare('SELECT * FROM users WHERE email=? AND role="admin" LIMIT 1');$s->execute([$email]);$u=$s->fetch();if(!$u||!password_verify($senha,$u['senha']))$err='Credenciais administrativas inválidas.';elseif($u['status']!=='active')$err='Administrador bloqueado.';else{login_user((int)$u['id']);redirect('admin/index.php');}} ?>
<?php layout_header('Login administrativo'); ?><div class="auth-card"><img class="auth-logo theme-logo theme-logo-dark" src="<?=e(url('assets/img/heal-logo.png'))?>"><img class="auth-logo theme-logo theme-logo-light" src="<?=e(url('assets/img/heal-logo-light.png'))?>"><h1>Área administrativa</h1><p class="subtitle">Gerencie alunos, cursos, aulas, pagamentos e certificados.</p><?php if($err): ?><div class="form-error"><?=e($err)?></div><?php endif; ?><form method="post"><?=csrf_field()?><label>E-mail</label><input type="email" name="email" value="admin@localhost" required><label>Senha</label><input type="password" name="senha" required><button class="btn">Entrar no painel</button></form><p class="login-hint">Acesso inicial local: <strong>admin@localhost</strong> / <strong>admin123</strong>. Altere depois.</p></div><?php layout_footer(); ?>
